        /**
         * ISO-8601 instant, exclusive
         */
        to?: string;
        /**
         * Page Number
         */
        page?: number;
        /**
         * Result Size, capped at 100
         */
        limit?: number;
        /**
         * Ascending or Descending (default) by time
         */
