export type CountWorkflowRunsData = {
    body?: never;
    path: {
        /**
         * Owning workspace name.
         */
        workspace: string;
    };
    query?: {
        /**
         * List of url encoded labels. For example Organization=Boomerang,customKey=test would be encoded as Organization%3DBoomerang,customKey%3Dtest)
         */
        labels?: Array<string>;
        /**
         * List of Workflow IDs  to filter for. Does not validate the IDs provided. Defaults to all.
         */
        workflows?: Array<string>;
        /**
         * The unix timestamp / date to search from in milliseconds since epoch
         */
        fromDate?: number;
        /**
         * The unix timestamp / date to search to in milliseconds since epoch
         */
        toDate?: number;
    };
    url: '/api/v2/workspace/{workspace}/workflowrun/count';
};

export type CountWorkflowRunsErrors = {
    /**
     * Bad Request
     */
    400: WorkflowRunCount;
};

export type CountWorkflowRunsError = CountWorkflowRunsErrors[keyof CountWorkflowRunsErrors];

export type CountWorkflowRunsResponses = {
    /**
     * OK
     */
    200: WorkflowRunCount;
};

export type CountWorkflowRunsResponse = CountWorkflowRunsResponses[keyof CountWorkflowRunsResponses];

export type QueryWorkflowRunsData = {
    body?: never;
    path: {
        /**
         * Owning workspace name.
         */
        workspace: string;
    };
    query: {
        /**
         * List of url encoded labels. For example Organization=Boomerang,customKey=test would be encoded as Organization%3DBoomerang,customKey%3Dtest)
         */
        labels?: Array<string>;
        /**
         * List of statuses to filter for. Defaults to all.
         */
        statuses?: Array<string>;
        /**
         * List of phases to filter for. Defaults to all.
         */
        phase?: Array<string>;
        /**
         * List of WorkflowRun IDs to filter for.
         */
        workflowruns?: Array<string>;
        /**
         * List of Workflow IDs to filter for.
         */
        workflows?: Array<string>;
        /**
         * List of Triggers to filter for.
         */
        triggers?: Array<string>;
        /**
         * Result Size
         */
        limit: number;
        /**
         * Page Number
         */
        page: number;
        /**
         * Ascending (ASC) or Descending (DESC) sort order on creationDate
         */
        order: 'ASC' | 'DESC';
        /**
         * The unix timestamp / date to search from in milliseconds since epoch
         */
        fromDate?: number;
        /**
         * The unix timestamp / date to search to in milliseconds since epoch
         */
        toDate?: number;
    };
    url: '/api/v2/workspace/{workspace}/workflowrun/query';
};

export type QueryWorkflowRunsErrors = {
    /**
     * Bad Request
     */
    400: PageWorkflowRun;
};

export type QueryWorkflowRunsError = QueryWorkflowRunsErrors[keyof QueryWorkflowRunsErrors];

export type QueryWorkflowRunsResponses = {
    /**
     * OK
     */
    200: PageWorkflowRun;
};

export type QueryWorkflowRunsResponse = QueryWorkflowRunsResponses[keyof QueryWorkflowRunsResponses];

